script:
country_event = {
	id = shroud_forged.1

	hide_window = yes
	is_triggered_only = yes

	immediate = {
		set_country_flag = shroud_forged_first_approach
		capital_scope = { # Set the right tone for the system they are in
			add_zone = {
				replace = yes
				district = district_nexus
				zone = zone_industrial
				zone_slot = 2
			}
			add_building = {
				building = building_foundry_1
				zone = zone_industrial
			}
			while = {
				count = @max_open_shroud_rift_uses
				add_deposit = d_shroud_rift_deposit
			}
			set_carrier_flag = origin_shroud_forged_capital_flag
			create_ambient_object = {
				type = "nebula_L6_entity"
				location = this
			}
			last_created_ambient_object = {
				set_location = {
					target = prev
					distance = 0
					angle = random
				}
			}

			create_ambient_object = {
				type = shroud_rift_object
				scale = 0.5
				entity_offset_height = -17
				location = this
			}
			last_created_ambient_object = {
				set_location = {
					target = prev
				}
			}
		}
		solar_system = {
			set_star_class = sc_m
		}
		add_resource = { consumer_goods = 200 }
		start_situation = {
			type = situation_shroud_forged
			target = root
		}
	}
}

trigger:
is_triggered_only = yes
trigger = {
		has_origin = origin_shroud_forged
		any_situation = {
			is_situation_type = situation_shroud_forged
		}
	}

